"""Derive SkyyCoins/build_skyycoins_0.1.12.py from the LIVE SkyyCoins 0.1.11 (build_skyycoins_0.1.11.py = the tools/deploy_set.py SET pin,
GENERATED by tools/coins_0_1_11_patch.py - never edit a generated script, edit this patch). Every anchor is asserted; at the end every change
is undone on a copy and compared with 0.1.11 (tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/coins_0_1_12_patch.py   then   python SkyyCoins/build_skyycoins_0.1.12.py   (never --deploy)
Check: python SkyyCoins/test_skyycoins_0.1.12.py [--keep]
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.1.12 (2026-11-14) = NO COIN DEATH PENALTY (round bank2, with SkyyBank 0.1.17 bank levels + SkyyVault 0.1.10 vault limits). Skyy
  2026-11-14 (docs/answered/economy.md): "remove the coin death penalty, and change the bank. ..." -> REPLACES 2026-10-15 "coins yes, loot no":
  no coins are lost on death.
  1. DEFAULTS 0 / 0: penaltyMin / penaltyMax default 5 / 5 -> 0 / 0 (the fields, the loader's fallbacks, the Server Setup rows, a fresh
     config.properties). The rows stay in Server Setup -> Coins -> Death (and /deathpenalty) so a server owner can switch a loss back on.
  2. ONE-TIME UPDATE CoinMigDeath0 (PROJECT-RULES 4; the reviewed CoinMigP7 text step, run right after it): config.properties penaltyMin=5 +
     penaltyMax=5 -> 0 / 0 ONLY when BOTH still read 5 / 5 (any other pair = an owner's own values: kept + one INFO line); the two value
     lines change in place (bytes, comments, order and CRLF / LF kept), verified that only the two keys differ; History copy first (verified);
     one config-changes.log row each (Undo in Server Setup -> Changes); the run-once marker comment written with it (a fresh file carries it).
     A 0.1.9-era file (10 / 25) goes 10 / 25 -> 5 / 5 (CoinMigP7) -> 0 / 0 (CoinMigDeath0) in the same start.
  3. With the loss at 0 a death sends NO chat line at all (0.1.11 still said "no coins lost here (a safe world)" on an island).
  4. No saved-data change, no new command / system / bridge key. ROLLBACK to 0.1.11: safe; 0.1.11 reads penaltyMin / penaltyMax 0 / 0 as
     admin values (no loss) - Undo the two CoinMigDeath0 rows in Server Setup -> Changes first to get 5 % back.
'''

P = G.Patch(os.path.join(ROOT, "SkyyCoins", "build_skyycoins_0.1.11.py"), os.path.join(ROOT, "SkyyCoins", "build_skyycoins_0.1.12.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.1.11"\n') and P.has("CoinMigP7") and P.has("structureMoney") and not P.has("CoinMigDeath0"), "not the generated SkyyCoins 0.1.11 script"
REG0, SYS0, CLS0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("pool.makeClass(")

P.rep('''"""SkyyCoins 0.1.11 - build script (javassist via jpype). GENERATED by tools/coins_0_1_11_patch.py from the LIVE 0.1.10 (itself generated
by tools/coins_0_1_10_patch.py from 0.1.9) - edit the patch.
Run:   python build_skyycoins_0.1.11.py           -> SkyyCoins/SkyyCoins-0.1.11.jar
''', '''"""SkyyCoins 0.1.12 - build script (javassist via jpype). GENERATED by tools/coins_0_1_12_patch.py from the LIVE 0.1.11 (itself generated
by tools/coins_0_1_11_patch.py from 0.1.10) - edit the patch.
Run:   python build_skyycoins_0.1.12.py           -> SkyyCoins/SkyyCoins-0.1.12.jar
''' + NOTE + '''0.1.11 notes:
''')
P.rep('VERSION = "0.1.11"\n', 'VERSION = "0.1.12"\n')

# ---- the default file: 0 / 0 + the 0.1.12 marker (a fresh file never needs the update)
P.rep('''P7_MARK = '# migrated: Balance P7 economy (SkyyCoins 0.1.10) - death coin loss 10-25 % -> 5 %, safe worlds, the coin curve (Server Setup -> Coins)'
''', '''P7_MARK = '# migrated: Balance P7 economy (SkyyCoins 0.1.10) - death coin loss 10-25 % -> 5 %, safe worlds, the coin curve (Server Setup -> Coins)'
D0_MARK_ID = 'no coin death penalty (SkyyCoins 0.1.12)'      # 0.1.12 (Skyy 2026-11-14 "remove the coin death penalty")
D0_MARK = '# migrated: no coin death penalty (SkyyCoins 0.1.12) - death coin loss 5 % -> 0 (Server Setup -> Coins -> Death can switch it back on)'
''')
P.rep('''            "# penaltyMin / penaltyMax = the percent of the CARRIED coins lost on a death (the bank is always safe); a random value in the range.\\n"''',
      '''            "# penaltyMin / penaltyMax = the percent of the CARRIED coins lost on a death (the bank is always safe); a random value in the range.\\n"
            "# 0 / 0 = no coins lost on death (the default since SkyyCoins 0.1.12, Skyy 2026-11-14).\\n"''')
P.rep('''            + P7_MARK + "\\n"
            "penaltyMin=5\\npenaltyMax=5\\npenalty.safeWorlds="''', '''            + P7_MARK + "\\n" + D0_MARK + "\\n"
            "penaltyMin=0\\npenaltyMax=0\\npenalty.safeWorlds="''')
P.rep('''cfg.addField(CtField.make("public static volatile int MIN = 5;", cfg))        # 0.1.10: was 10 (Skyy "Small coin loss" ~5 %)
cfg.addField(CtField.make("public static volatile int MAX = 5;", cfg))        # 0.1.10: was 25''',
      '''cfg.addField(CtField.make("public static volatile int MIN = 0;", cfg))        # 0.1.12: no coin death penalty (0.1.10: 5, was 10)
cfg.addField(CtField.make("public static volatile int MAX = 0;", cfg))        # 0.1.12: 0 (0.1.10: 5, was 25)''')
P.rep('''    int mn = Integer.parseInt(p.getProperty("penaltyMin", "5").trim());     // 0.1.10: defaults 5 / 5 (were 10 / 25)
    int mx = Integer.parseInt(p.getProperty("penaltyMax", "5").trim());''',
      '''    int mn = Integer.parseInt(p.getProperty("penaltyMin", "0").trim());     // 0.1.12: defaults 0 / 0 (0.1.10: 5 / 5, were 10 / 25)
    int mx = Integer.parseInt(p.getProperty("penaltyMax", "0").trim());''')
P.rep('''    if (mn > mx) {{ {PKG}.CoinStore.warn("config penaltyMin > penaltyMax, using defaults 5-5"); mn = 5; mx = 5; }}''',
      '''    if (mn > mx) {{ {PKG}.CoinStore.warn("config penaltyMin > penaltyMax, using defaults 0-0 (no coin loss)"); mn = 0; mx = 0; }}''')
P.rep('''    ("penaltyMin", "Coin loss on death, min", "death", "int", "5", "0", "100", "step=1", "%", "live",
     "Least % of the CARRIED coins a death costs (random from min to max). The bank is always safe.",''',
      '''    ("penaltyMin", "Coin loss on death, min", "death", "int", "0", "0", "100", "step=1", "%", "live",
     "Least % of the CARRIED coins a death costs (random from min to max). 0 = none. Bank coins are safe.",''')
P.rep('''    ("penaltyMax", "Coin loss on death, max", "death", "int", "5", "0", "100", "step=1", "%", "live",
     "Most % of the carried coins a death costs. Same as min = always that much.",''',
      '''    ("penaltyMax", "Coin loss on death, max", "death", "int", "0", "0", "100", "step=1", "%", "live",
     "Most % of the carried coins a death costs. 0 = no coin loss on death (the default).",''')

# ---- CoinMigDeath0: CoinMigP7's reviewed text step with the 0.1.12 constants (built from the 0.1.11 source text itself)
A0 = "# ================= 0.1.10 CoinMigP7: penaltyMin=10 + penaltyMax=25 -> 5 / 5"
A1 = "# ================= CoinTask (world thread) ================="
i0, i1 = P.s.index(A0), P.s.index(A1)
MIG = P.s[i0:i1]
assert MIG.count('mig = pool.makeClass(PKG + ".CoinMigP7")') == 1
D0 = MIG
for a, b in (('# ================= 0.1.10 CoinMigP7: penaltyMin=10 + penaltyMax=25 -> 5 / 5', '# ================= 0.1.12 CoinMigDeath0: penaltyMin=5 + penaltyMax=5 -> 0 / 0'),
             ('mig = pool.makeClass(PKG + ".CoinMigP7")', 'mig0 = pool.makeClass(PKG + ".CoinMigDeath0")'),
             ("'public static final String[] OLDV = new String[] { \"10\", \"25\" };'", "'public static final String[] OLDV = new String[] { \"5\", \"5\" };'"),
             ("'public static final String[] NEWV = new String[] { \"5\", \"5\" };'", "'public static final String[] NEWV = new String[] { \"0\", \"0\" };'"),
             ('json.dumps(P7_MARK)', 'json.dumps(D0_MARK)'), ('json.dumps(P7_MARK_ID)', 'json.dumps(D0_MARK_ID)'),
             ("'public static final String WHO = \"SkyyCoins 0.1.10\";'", "'public static final String WHO = \"SkyyCoins 0.1.12\";'"),
             ("# BOTH keys must be single lines holding exactly 10 / 25 to move", "# BOTH keys must be single lines holding exactly 5 / 5 to move"),
             ("for the 0.1.10 death coin loss", "for the 0.1.12 coin death penalty removal"),
             ('"before the 0.1.10 death coin loss (Balance P7)"', '"before the 0.1.12 coin death penalty removal"'),
             ('''"config.properties: coin loss on death (Balance P7, Skyy 'small coin loss'): " + (n > 0 ? "10-25 % -> 5 % of the carried coins" : "kept (an admin's values): " + kept) + "; no loss in worlds starting with " + @PKG@.CoinConfig.SAFE + " (Server Setup -> Coins -> Death; the old file is in config-history; Server Setup -> Changes can undo it)"''',
              '''"config.properties: coin loss on death (Skyy 2026-11-14 'remove the coin death penalty'): " + (n > 0 ? "5 % -> 0 (no coins lost on death)" : "kept (an admin's values): " + kept) + " (Server Setup -> Coins -> Death; the old file is in config-history; Server Setup -> Changes can undo it)"''')):
    assert D0.count(a) >= 1, "CoinMigDeath0 source anchor: " + a[:90]
    D0 = D0.replace(a, b)
D0 = D0.replace(", mig))", ", mig0))").replace("    mig.addField(", "    mig0.addField(").replace("mig.addMethod(", "mig0.addMethod(")
assert "mig)" not in D0 and "mig." not in D0 and "P7_MARK" not in D0 and "10 / 25" not in D0, "CoinMigDeath0: every CoinMigP7 reference renamed"
P.rep(A1, D0 + A1)

# ---- a zero loss sends no chat line (0.1.11 said "no coins lost here (a safe world)" on every island death)
P.rep('''      if (wn == null && balNow > 0L) {PKG}.CoinStore.warn(''', '''      if (wn == null && balNow > 0L && {PKG}.CoinConfig.MAX > 0) {PKG}.CoinStore.warn(''')
P.rep('''      if (balNow > 0L && {PKG}.CoinConfig.safeWorld(wn)) pr.sendMessage(''', '''      if (balNow > 0L && {PKG}.CoinConfig.MAX > 0 && {PKG}.CoinConfig.safeWorld(wn)) pr.sendMessage(''')

# ---- setup: the 0.1.12 update right after CoinMigP7 (it re-reads the file); the ready line
P.rep('''  String p7 = {PKG}.CoinMigP7.run({PKG}.CoinConfig.FILE);   // 0.1.10 Balance P7: 10-25 % -> 5 % once (History first; Undo); re-reads the file''',
      '''  String p7 = {PKG}.CoinMigP7.run({PKG}.CoinConfig.FILE);   // 0.1.10 Balance P7: 10-25 % -> 5 % once (History first; Undo); re-reads the file
  String d0 = {PKG}.CoinMigDeath0.run({PKG}.CoinConfig.FILE);   // 0.1.12: 5 % -> 0 once (no coin death penalty; History first; Undo)''')
P.rep('''(p7.length() > 0 ? "; migrated 0.1.10" : "") + "); Structure Money''',
      '''(p7.length() > 0 ? "; migrated 0.1.10" : "") + (d0.length() > 0 ? "; migrated 0.1.12" : "") + ({PKG}.CoinConfig.MAX <= 0 ? "; no coins lost on death" : "") + "); Structure Money''')
P.rep('''for c in (cs, cfg, xfr, fn, crb, cio, cev, task, tick, bal, pay, give, dp, dps, pl, ccv, mig):   # 0.1.8: + CoinXfer; 0.1.10: + CoinCurve, CoinMigP7''',
      '''for c in (cs, cfg, xfr, fn, crb, cio, cev, task, tick, bal, pay, give, dp, dps, pl, ccv, mig, mig0):   # 0.1.8: + CoinXfer; 0.1.10: + CoinCurve, CoinMigP7; 0.1.12: + CoinMigDeath0''')
P.rep('''configurable death penalty (/deathpenalty 5% or 5%-10%; none on your island / in shard worlds)''',
      '''no coin death penalty by default (an owner can set one: /deathpenalty 5% or 5%-10%; never on your island / in shard worlds)''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("pool.makeClass(") == CLS0 + 1, "0.1.12 adds one class (CoinMigDeath0), no command / system"
_i = P.s.index
assert _i('mig0 = pool.makeClass(PKG + ".CoinMigDeath0")') > _i('mig = pool.makeClass(PKG + ".CoinMigP7")') and _i("CoinMigDeath0.run(") > _i("CoinMigP7.run(")
P.finish()
